1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
12		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
13		"github.com/spf13/cobra"
14	)
15	
16	type tokensProfileReport struct {
17		Source                   string                        `json:"source"`
18		CheckpointsAvailable     int                           `json:"checkpoints_available"`
19		CheckpointsAnalyzed      int                           `json:"checkpoints_analyzed"`
20		CheckpointsWithTokenData int                           `json:"checkpoints_with_token_data"`
21		MissingTokenData         int                           `json:"missing_token_data"`
22		MetadataReadWarnings     int                           `json:"metadata_read_warnings,omitempty"`
23		Tokens                   *sessionTokensUsage           `json:"tokens,omitempty"`
24		Signals                  []tokensProfileSignal         `json:"signals,omitempty"`
25		Recommendations          []sessionTokensRecommendation `json:"recommendations,omitempty"`
26		Limitations              []string                      `json:"limitations,omitempty"`
27	}
28	
29	type tokensProfileSignal struct {
30		ID            string   `json:"id"`
31		Label         string   `json:"label"`
32		Count         int      `json:"count"`
33		Percent       int      `json:"percent"`
34		CheckpointIDs []string `json:"checkpoint_ids,omitempty"`
35	}
36	
37	type tokensProfileSignalDefinition struct {
38		id    string
39		label string
40	}
41	
42	var tokensProfileSignalDefinitions = []tokensProfileSignalDefinition{
43		{id: "context-replay-hotspot", label: "Cache/context replay hotspot"},
44		{id: "api-call-amplification", label: "API call amplification"},
45		{id: "subagent-heavy", label: "Subagent-heavy sessions"},
46		{id: "missing-token-data", label: "Missing token data"},
47	}
48	
49	func newTokensGroupCmd() *cobra.Command {
50		cmd := &cobra.Command{
51			Use:   "tokens",
52			Short: "Analyze token usage across sessions and checkpoints",
53			Long: `Analyze token usage across sessions and checkpoints.
54	
55	Commands:
56	  profile  Aggregate token usage across committed checkpoints
57	
58	Examples:
59	  entire tokens profile
60	  entire tokens profile --json`,
61			RunE: func(cmd *cobra.Command, _ []string) error {
62				return cmd.Help()
63			},
64		}
65	
66		cmd.AddCommand(newTokensProfileCmd())
67		return cmd
68	}
69	
70	func newTokensProfileCmd() *cobra.Command {
71		var jsonFlag bool
72		var limitFlag int
73		var allFlag bool
74	
75		cmd := &cobra.Command{
76			Use:   "profile",
77			Short: "Aggregate token usage and recommendations across checkpoint history",
78			Long: `Aggregate token usage and recommendations across committed checkpoint history.
79	
80	The profile reads committed checkpoint metadata only. It does not inspect
81	transcripts or source files, so it is deterministic and avoids adding token
82	cost while diagnosing token usage. By default it scans the latest 50 committed
83	checkpoints; use --limit or --all to change the scope.`,
84			Args: cobra.NoArgs,
85			RunE: func(cmd *cobra.Command, _ []string) error {
86				limit := limitFlag
87				if allFlag {
88					limit = 0
89				} else if limit <= 0 {
90					return errors.New("--limit must be positive unless --all is used")
91				}
92				return runTokensProfile(cmd.Context(), cmd, jsonFlag, limit)
93			},
94		}
95	
96		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
97		cmd.Flags().IntVar(&limitFlag, "limit", 50, "Maximum committed checkpoints to analyze")
98		cmd.Flags().BoolVar(&allFlag, "all", false, "Analyze all committed checkpoints")
99		return cmd
100	}
101	
102	func runTokensProfile(ctx context.Context, cmd *cobra.Command, jsonOutput bool, limit int) error {
103		repo, err := openRepository(ctx)
104		if err != nil {
105			cmd.SilenceUsage = true
106			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository.")
107			return NewSilentError(err)
108		}
109		defer repo.Close()
110	
111		store := checkpoint.NewCommittedReadStore(ctx, repo)
112		infos, err := store.ListCommitted(ctx)
113		if err != nil {
114			return fmt.Errorf("failed to list checkpoints: %w", err)
115		}
116	
117		report, err := buildTokensProfileReport(ctx, store, infos, limit)
118		if err != nil {
119			return err
120		}
121	
122		if jsonOutput {
123			return writeTokensProfileJSON(cmd.OutOrStdout(), report)
124		}
125		writeTokensProfileText(cmd.OutOrStdout(), report)
126		return nil
127	}
128	
129	func buildTokensProfileReport(ctx context.Context, store *checkpoint.GitStore, infos []checkpoint.CommittedInfo, limit int) (tokensProfileReport, error) {
130		checkpointsAvailable := len(infos)
131		infos = limitTokensProfileCheckpoints(infos, limit)
132		report := tokensProfileReport{
133			Source:               "committed_checkpoints",
134			CheckpointsAvailable: checkpointsAvailable,
135			CheckpointsAnalyzed:  len(infos),
136		}
137		signals := make(map[string]*tokensProfileSignal, len(tokensProfileSignalDefinitions))
138		var aggregate *agent.TokenUsage
139	
140		for _, info := range infos {
141			if err := ctx.Err(); err != nil {
142				return tokensProfileReport{}, err //nolint:wrapcheck // Propagating context cancellation.
143			}
144	
145			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
146			if err != nil {
147				return tokensProfileReport{}, fmt.Errorf("failed to read checkpoint %s: %w", info.CheckpointID, err)
148			}
149			if summary == nil {
150				report.MissingTokenData++
151				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
152				continue
153			}
154	
155			usage, metadataReadWarning, err := tokensProfileCheckpointUsage(ctx, store, info.CheckpointID, summary)
156			if err != nil {
157				return tokensProfileReport{}, err
158			}
159			if metadataReadWarning {
160				report.MetadataReadWarnings++
161			}
162			tokens := buildSessionTokensUsage(usage)
163			if tokens == nil {
164				report.MissingTokenData++
165				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
166				continue
167			}
168	
169			report.CheckpointsWithTokenData++
170			aggregate = addCheckpointTokenUsage(aggregate, usage)
171			addTokensProfileTokenSignals(signals, info.CheckpointID, tokens, report.CheckpointsAnalyzed)
172		}
173	
174		report.Tokens = buildSessionTokensUsage(aggregate)
175		report.Signals = orderedTokensProfileSignals(signals)
176		report.Recommendations = tokensProfileRecommendations(report)
177		report.Limitations = tokensProfileLimitations(report)
178		return report, nil
179	}
180	
181	func limitTokensProfileCheckpoints(infos []checkpoint.CommittedInfo, limit int) []checkpoint.CommittedInfo {
182		if limit <= 0 || len(infos) <= limit {
183			return infos
184		}
185		return infos[:limit]
186	}
187	
188	func tokensProfileCheckpointUsage(ctx context.Context, store *checkpoint.GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*agent.TokenUsage, bool, error) {
189		if summary == nil {
190			return nil, false, nil
191		}
192	
193		metas := make([]*checkpoint.CommittedMetadata, 0, len(summary.Sessions))
194		metadataReadWarning := false
195		for i := range len(summary.Sessions) {
196			meta, err := store.ReadSessionMetadata(ctx, checkpointID, i)
197			if err != nil {
198				if ctxErr := ctx.Err(); ctxErr != nil {
199					return nil, false, ctxErr //nolint:wrapcheck // Propagating context cancellation.
200				}
201				metadataReadWarning = true
202				continue
203			}
204			metas = append(metas, meta)
205		}
206		sessionUsage := aggregateCheckpointTokenUsage(metas)
207		if !metadataReadWarning && sessionUsage != nil {
208			return sessionUsage, false, nil
209		}
210		if summary.TokenUsage != nil {
211			return summary.TokenUsage, metadataReadWarning, nil
212		}
213		return sessionUsage, metadataReadWarning, nil
214	}
215	
216	func addTokensProfileTokenSignals(signals map[string]*tokensProfileSignal, checkpointID id.CheckpointID, tokens *sessionTokensUsage, denominator int) {
217		if tokens == nil {
218			return
219		}
220		if tokens.Total > 0 && tokenPercent(tokens.CacheRead, tokens.Total) >= 80 {
221			addTokensProfileSignal(signals, "context-replay-hotspot", checkpointID, denominator)
222		}
223		if tokens.APICalls >= 20 {
224			addTokensProfileSignal(signals, "api-call-amplification", checkpointID, denominator)
225		}
226		if tokens.Total > 0 && tokens.SubagentTotal*100 >= tokens.Total*10 {
227			addTokensProfileSignal(signals, "subagent-heavy", checkpointID, denominator)
228		}
229	}
230	
231	func addTokensProfileSignal(signals map[string]*tokensProfileSignal, signalID string, checkpointID id.CheckpointID, denominator int) {
232		signal := signals[signalID]
233		if signal == nil {
234			definition := tokensProfileSignalDefinitionFor(signalID)
235			signal = &tokensProfileSignal{
236				ID:    definition.id,
237				Label: definition.label,
238			}
239			signals[signalID] = signal
240		}
241		signal.Count++
242		if denominator > 0 {
243			signal.Percent = roundedPercent(signal.Count, denominator)
244		}
245		if checkpointID != "" {
246			signal.CheckpointIDs = append(signal.CheckpointIDs, checkpointID.String())
247		}
248	}
249	
250	func tokensProfileSignalDefinitionFor(signalID string) tokensProfileSignalDefinition {
251		for _, definition := range tokensProfileSignalDefinitions {
252			if definition.id == signalID {
253				return definition
254			}
255		}
256		return tokensProfileSignalDefinition{id: signalID, label: signalID}
257	}
258	
259	func orderedTokensProfileSignals(signals map[string]*tokensProfileSignal) []tokensProfileSignal {
260		ordered := make([]tokensProfileSignal, 0, len(signals))
261		for _, definition := range tokensProfileSignalDefinitions {
262			if signal := signals[definition.id]; signal != nil {
263				ordered = append(ordered, *signal)
264			}
265		}
266		return ordered
267	}
268	
269	func tokensProfileRecommendations(report tokensProfileReport) []sessionTokensRecommendation {
270		var recs []sessionTokensRecommendation
271	
272		if report.CheckpointsAnalyzed == 0 {
273			return []sessionTokensRecommendation{{
274				ID:       "no-checkpoints",
275				Severity: "low",
276				Message:  "Create checkpoints first; token profiling needs committed checkpoint metadata to identify patterns.",
277				Signals:  []string{"empty_checkpoint_history"},
278			}}
279		}
280	
281		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 ||
282			tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
283			recs = append(recs, sessionTokensRecommendation{
284				ID:       "search-before-reinvestigation",
285				Severity: "high",
286				Message:  "Use `entire search` for prior decisions/checkpoints before broad re-investigation.",
287				Signals:  []string{"cache_read_tokens", "api_call_count"},
288			})
289		}
290		if tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
291			recs = append(recs, sessionTokensRecommendation{
292				ID:       "batch-diagnostics",
293				Severity: "medium",
294				Message:  "Batch diagnostic reads around one narrowed hypothesis when API call amplification repeats.",
295				Signals:  []string{"api_call_count"},
296			})
297		}
298		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 {
299			recs = append(recs, sessionTokensRecommendation{
300				ID:       "preserve-then-compact",
301				Severity: "medium",
302				Message:  "Summarize useful findings before continuing large-context work; compact or restart only after preserving relevant context.",
303				Signals:  []string{"cache_read_tokens"},
304			})
305		}
306		if tokensProfileSignalCount(report.Signals, "subagent-heavy") > 0 {
307			recs = append(recs, sessionTokensRecommendation{
308				ID:       "scope-subagents",
309				Severity: "medium",
310				Message:  "Scope subagent tasks tightly with a narrow objective and expected output.",
311				Signals:  []string{"subagent_tokens"},
312			})
313		}
314		if report.MissingTokenData > 0 {
315			recs = append(recs, sessionTokensRecommendation{
316				ID:       "improve-token-coverage",
317				Severity: "low",
318				Message:  "Increase token coverage by using agents and checkpoints that report token usage.",
319				Signals:  []string{"missing_token_usage"},
320			})
321		}
322	
323		if len(recs) == 0 {
324			recs = append(recs, sessionTokensRecommendation{
325				ID:       "no-repeated-hotspots",
326				Severity: "low",
327				Message:  "No repeated token hotspots were visible in committed checkpoint metadata.",
328				Signals:  []string{"checkpoint_token_metadata"},
329			})
330		}
331		return recs
332	}
333	
334	func tokensProfileSignalCount(signals []tokensProfileSignal, signalID string) int {
335		for _, signal := range signals {
336			if signal.ID == signalID {
337				return signal.Count
338			}
339		}
340		return 0
341	}
342	
343	func tokensProfileLimitations(report tokensProfileReport) []string {
344		var limitations []string
345		if report.CheckpointsAvailable > report.CheckpointsAnalyzed {
346			limitations = append(limitations, fmt.Sprintf("Limited to latest %d of %d committed checkpoints; use --limit or --all to change scope.", report.CheckpointsAnalyzed, report.CheckpointsAvailable))
347		}
348		if report.CheckpointsAnalyzed == 0 {
349			limitations = append(limitations, "No committed checkpoints found.")
350		}
351		if report.MissingTokenData > 0 {
352			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s did not include token usage.", report.MissingTokenData, pluralSuffix(report.MissingTokenData)))
353		}
354		if report.MetadataReadWarnings > 0 {
355			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s had incomplete session metadata; profile used root token summaries or readable sessions where available.", report.MetadataReadWarnings, pluralSuffix(report.MetadataReadWarnings)))
356		}
357		if report.CheckpointsAnalyzed > 0 {
358			limitations = append(limitations, "Tool-level search/read spend is not captured yet; this profile infers patterns from token totals, cache/context replay, API call counts, and subagent totals.")
359		}
360		return limitations
361	}
362	
363	func writeTokensProfileJSON(w io.Writer, report tokensProfileReport) error {
364		enc := json.NewEncoder(w)
365		enc.SetIndent("", "  ")
366		if err := enc.Encode(report); err != nil {
367			return fmt.Errorf("failed to encode token profile report: %w", err)
368		}
369		return nil
370	}
371	
372	func writeTokensProfileText(w io.Writer, report tokensProfileReport) {
373		fmt.Fprintln(w, "Token profile")
374		fmt.Fprintln(w)
375		fmt.Fprintf(w, "Source:               %s\n", report.Source)
376		fmt.Fprintf(w, "Checkpoints available: %d\n", report.CheckpointsAvailable)
377		fmt.Fprintf(w, "Checkpoints analyzed: %d\n", report.CheckpointsAnalyzed)
378		fmt.Fprintf(w, "With token data:      %d\n", report.CheckpointsWithTokenData)
379		fmt.Fprintf(w, "Missing token data:   %d\n", report.MissingTokenData)
380		if report.MetadataReadWarnings > 0 {
381			fmt.Fprintf(w, "Metadata warnings:    %d\n", report.MetadataReadWarnings)
382		}
383	
384		writeTokenUsageSection(w, report.Tokens)
385		writeTokensProfileSignals(w, report.Signals)
386		if len(report.Recommendations) > 0 {
387			writeTokenRecommendations(w, report.Recommendations)
388		}
389		writeTokenLimitations(w, report.Limitations)
390	}
391	
392	func writeTokensProfileSignals(w io.Writer, signals []tokensProfileSignal) {
393		if len(signals) == 0 {
394			return
395		}
396	
397		fmt.Fprintln(w)
398		fmt.Fprintln(w, "Repeated signals")
399		for _, signal := range signals {
400			fmt.Fprintf(w, "- %s: %d checkpoint%s", signal.Label, signal.Count, pluralSuffix(signal.Count))
401			if signal.Percent > 0 {
402				fmt.Fprintf(w, " (%d%%)", signal.Percent)
403			}
404			fmt.Fprintln(w)
405		}
406	}
407	
408	func pluralSuffix(count int) string {
409		if count == 1 {
410			return ""
411		}
412		return "s"
413	}
