108	func runSessionTokens(ctx context.Context, cmd *cobra.Command, sessionID string, current, jsonOutput, agentBrief bool) error {
109		if sessionID == "" || current {
110			sessionID = strategy.FindMostRecentSession(ctx)
111			if sessionID == "" {
112				fmt.Fprintln(cmd.OutOrStdout(), "No active session found in this worktree.")
113				return nil
114			}
115		}
116	
117		state, err := strategy.LoadSessionState(ctx, sessionID)
118		if err != nil {
119			return fmt.Errorf("failed to load session: %w", err)
120		}
121		if state == nil {
122			cmd.SilenceUsage = true
123			fmt.Fprintln(cmd.ErrOrStderr(), "Session not found.")
124			return NewSilentError(fmt.Errorf("session not found: %s", sessionID))
125		}
126	
127		report := buildSessionTokensReport(state, sessionPhaseLabel(state))
128		if jsonOutput {
129			return writeSessionTokensJSON(cmd.OutOrStdout(), report)
130		}
131		if agentBrief {
132			writeSessionTokensAgentBrief(cmd.OutOrStdout(), report)
