139	func buildSessionTokensReport(state *strategy.SessionState, status string) sessionTokensReport {
140		agentLabel := string(state.AgentType)
141		if agentLabel == "" {
142			agentLabel = unknownPlaceholder
143		}
144	
145		report := sessionTokensReport{
146			SessionID: state.SessionID,
147			Agent:     agentLabel,
148			Model:     state.ModelName,
149			Status:    status,
150			Source:    "session_state",
151		}
152	
153		if tokens := buildSessionTokensUsage(state.TokenUsage); tokens != nil {
154			report.Tokens = tokens
155			if tokens.SubagentTotal > 0 {
156				report.Contributors = append(report.Contributors, sessionTokensContributor{
157					Kind:       "subagents",
158					Label:      "Subagents",
159					Tokens:     tokens.SubagentTotal,
160					Confidence: "reported",
161					Signals:    []string{"subagent_tokens"},
162				})
163			}
164		} else {
165			report.Limitations = append(report.Limitations, "No token usage recorded for this session.")
166			report.Recommendations = append(report.Recommendations, sessionTokensRecommendation{
167				ID:       "no-token-data",
168				Severity: "low",
169				Message:  "Token usage is unavailable for this session; the agent may not expose token data yet, or no checkpoint has captured it.",
170				Signals:  []string{"missing_token_usage"},
171			})
172		}
173	
174		if contextInfo := buildSessionTokensContext(state.ContextTokens, state.ContextWindowSize); contextInfo != nil {
175			report.Context = contextInfo
176			report.Contributors = append(report.Contributors, sessionTokensContributor{
177				Kind:       "context_pressure",
178				Label:      "Context pressure",
179				Percent:    contextInfo.Percent,
180				Confidence: "reported",
181				Signals:    []string{"context_tokens"},
182			})
183		}
184	
185		if labels := skillEventLabels(state.SkillEvents); len(labels) > 0 {
186			report.Contributors = append(report.Contributors, sessionTokensContributor{
187				Kind:       "skills",
188				Label:      "Skills/slash commands: " + strings.Join(labels, ", "),
189				Confidence: "reported",
190				Signals:    []string{"skill_events"},
191			})
192		}
193	
194		report.Recommendations = append(report.Recommendations, recommendationRules(tokenRecommendationSignals{
195			Tokens:          report.Tokens,
