115		if err != nil {
116			return checkpointTokensReport{}, lookup, err
117		}
118	
119		summary, err := lookup.store.ReadCommitted(ctx, cpID)
120		if err != nil {
121			return checkpointTokensReport{}, lookup, fmt.Errorf("failed to read checkpoint: %w", err)
122		}
123		if summary == nil || len(summary.Sessions) == 0 {
124			cmd.SilenceUsage = true
125			fmt.Fprintln(cmd.ErrOrStderr(), "Checkpoint not found.")
126			return checkpointTokensReport{}, lookup, NewSilentError(fmt.Errorf("%w: %s", checkpoint.ErrCheckpointNotFound, checkpointIDPrefix))
127		}
128	
129		metas := make([]*checkpoint.CommittedMetadata, 0, len(summary.Sessions))
130		for i := range len(summary.Sessions) {
131			meta, err := lookup.store.ReadSessionMetadata(ctx, cpID, i)
132			if err != nil {
133				return checkpointTokensReport{}, lookup, fmt.Errorf("failed to read checkpoint session %d metadata: %w", i, err)
134			}
135			metas = append(metas, meta)
136		}
137	
138		return buildCheckpointTokensReport(cpID, summary, metas), lookup, nil
139	}
