281	func firstCheckpointBranch(metas []*checkpoint.CommittedMetadata) string {
282		for _, meta := range metas {
283			if meta != nil && meta.Branch != "" {
284				return meta.Branch
285			}
286		}
287		return ""
288	}
289	
290	func aggregateCheckpointTokenUsage(metas []*checkpoint.CommittedMetadata) *agent.TokenUsage {
291		var total *agent.TokenUsage
292		for _, meta := range metas {
293			if meta == nil {
294				continue
295			}
296			total = addCheckpointTokenUsage(total, meta.TokenUsage)
297		}
298		return total
299	}
300	
301	func addCheckpointTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
302		if a == nil && b == nil {
303			return nil
304		}
305		result := &agent.TokenUsage{}
306		if a != nil {
307			result.InputTokens = a.InputTokens
308			result.CacheCreationTokens = a.CacheCreationTokens
309			result.CacheReadTokens = a.CacheReadTokens
310			result.OutputTokens = a.OutputTokens
311			result.APICallCount = a.APICallCount
312		}
313		if b != nil {
314			result.InputTokens += b.InputTokens
315			result.CacheCreationTokens += b.CacheCreationTokens
316			result.CacheReadTokens += b.CacheReadTokens
317			result.OutputTokens += b.OutputTokens
318			result.APICallCount += b.APICallCount
319		}
320		result.SubagentTokens = addCheckpointTokenUsage(tokenUsageSubagents(a), tokenUsageSubagents(b))
321		return result
322	}
323	
324	func tokenUsageSubagents(usage *agent.TokenUsage) *agent.TokenUsage {
325		if usage == nil {
326			return nil
327		}
328		return usage.SubagentTokens
329	}
330	
331	func buildCheckpointTokensComparison(target, baseline checkpointTokensReport) *checkpointTokensComparison {
332		comparison := &checkpointTokensComparison{
333			BaselineCheckpointID: baseline.CheckpointID,
334			TargetCheckpointID:   target.CheckpointID,
335		}
336		if target.Tokens == nil || baseline.Tokens == nil {
337			comparison.Status = checkpointComparisonStatusUnavailable
338			comparison.Qualification = "Comparison unavailable because token usage is missing for one checkpoint."
339			comparison.Limitations = append(comparison.Limitations, comparison.Qualification)
340			return comparison
341		}
342	
343		comparison.Total = buildCheckpointMetricDelta(baseline.Tokens.Total, target.Tokens.Total)
344		comparison.CacheRead = buildCheckpointMetricDelta(baseline.Tokens.CacheRead, target.Tokens.CacheRead)
345		comparison.APICalls = buildCheckpointMetricDelta(baseline.Tokens.APICalls, target.Tokens.APICalls)
346		comparison.Status = checkpointComparisonStatus(comparison.Total)
347		comparison.Qualification = checkpointComparisonQualification(comparison.Status)
348		return comparison
349	}
350	
351	func buildCheckpointMetricDelta(baseline, current int) *checkpointTokensMetricDelta {
352		delta := &checkpointTokensMetricDelta{
353			Baseline:  baseline,
354			Current:   current,
355			Change:    current - baseline,
356			Direction: checkpointDeltaDirection(current - baseline),
357		}
358		if baseline != 0 {
359			percent := float64(delta.Change) * 100 / float64(baseline)
360			delta.ChangePercent = &percent
361		}
362		return delta
363	}
364	
365	func checkpointDeltaDirection(change int) string {
366		switch {
367		case change < 0:
368			return "down"
369		case change > 0:
370			return "up"
371		default:
372			return "unchanged"
373		}
374	}
375	
376	func checkpointComparisonStatus(total *checkpointTokensMetricDelta) string {
377		if total == nil {
378			return checkpointComparisonStatusUnavailable
379		}
380		switch total.Direction {
381		case "down":
382			return checkpointComparisonStatusObservedReduction
383		case "up":
384			return checkpointComparisonStatusObservedIncrease
385		default:
386			return checkpointComparisonStatusObservedNoChange
387		}
388	}
389	
390	func checkpointComparisonQualification(status string) string {
391		switch status {
392		case checkpointComparisonStatusObservedReduction:
393			return "Observed token use decreased for this checkpoint comparison. This does not prove quality was preserved; verify the task outcome or tests before treating it as a successful optimization."
394		case checkpointComparisonStatusObservedIncrease:
395			return "Observed token use increased for this checkpoint comparison. Check whether the extra context was necessary before treating it as waste."
396		case checkpointComparisonStatusObservedNoChange:
397			return "Observed token use was unchanged for this checkpoint comparison. Quality still depends on the task outcome, not token totals alone."
398		default:
399			return "Comparison unavailable because token usage is missing for one checkpoint."
400		}
401	}
402	
403	func writeCheckpointTokensJSON(w io.Writer, report checkpointTokensReport) error {
404		enc := json.NewEncoder(w)
405		enc.SetIndent("", "  ")
406		if err := enc.Encode(report); err != nil {
407			return fmt.Errorf("failed to encode checkpoint token report: %w", err)
408		}
409		return nil
410	}
411	
412	func writeCheckpointTokensText(w io.Writer, report checkpointTokensReport) {
413		fmt.Fprintln(w, "Checkpoint tokens")
414		fmt.Fprintln(w)
415		fmt.Fprintf(w, "Checkpoint: %s\n", report.CheckpointID)
416		switch {
417		case report.SessionCount > 1:
418			fmt.Fprintf(w, "Sessions:   %d\n", report.SessionCount)
419			if len(report.Agents) > 0 {
420				fmt.Fprintf(w, "Agents:     %s\n", strings.Join(report.Agents, ", "))
421			}
422			if len(report.Models) > 0 {
423				fmt.Fprintf(w, "Models:     %s\n", strings.Join(report.Models, ", "))
424			}
425		case report.SessionID != "":
426			fmt.Fprintf(w, "Session:    %s\n", report.SessionID)
427			if report.Agent != "" {
428				fmt.Fprintf(w, "Agent:      %s\n", report.Agent)
429			}
430			if report.Model != "" {
431				fmt.Fprintf(w, "Model:      %s\n", report.Model)
432			}
433		case report.Agent != "":
434			fmt.Fprintf(w, "Agent:      %s\n", report.Agent)
435		}
436		if report.Branch != "" {
437			fmt.Fprintf(w, "Branch:     %s\n", report.Branch)
438		}
439	
440		writeTokenUsageSection(w, report.Tokens)
441		writeCheckpointTokenComparison(w, report.Comparison)
442		if len(report.Recommendations) > 0 {
443			writeTokenRecommendations(w, report.Recommendations)
444		}
445		writeTokenContributors(w, report.Contributors, report.Context)
446		writeTokenLimitations(w, report.Limitations)
447	}
448	
449	func writeCheckpointTokenComparison(w io.Writer, comparison *checkpointTokensComparison) {
450		if comparison == nil {
451			return
452		}
453	
454		fmt.Fprintln(w)
455		fmt.Fprintln(w, "Comparison")
456		fmt.Fprintf(w, "Baseline: %s\n", comparison.BaselineCheckpointID)
457		if comparison.Status != checkpointComparisonStatusUnavailable {
458			fmt.Fprintf(w, "Total tokens: %s\n", formatCheckpointMetricDelta(comparison.Total, formatTokenCount))
459			fmt.Fprintf(w, "Cache/context replay: %s\n", formatCheckpointMetricDelta(comparison.CacheRead, formatTokenCount))
460			fmt.Fprintf(w, "API calls: %s\n", formatCheckpointMetricDelta(comparison.APICalls, formatPlainCount))
461		}
462		fmt.Fprintln(w)
463		fmt.Fprintln(w, "Qualification")
464		fmt.Fprintln(w, comparison.Qualification)
465	}
466	
467	func formatCheckpointMetricDelta(delta *checkpointTokensMetricDelta, formatValue func(int) string) string {
468		if delta == nil {
469			return "unavailable"
470		}
471		from := formatValue(delta.Baseline)
472		to := formatValue(delta.Current)
473		if delta.Direction == "unchanged" {
474			return fmt.Sprintf("unchanged (%s -> %s)", from, to)
475		}
476		if delta.ChangePercent == nil {
477			return fmt.Sprintf("%s (%s -> %s)", delta.Direction, from, to)
478		}
479		return fmt.Sprintf("%s %s (%s -> %s)", delta.Direction, formatPercent(absFloat(*delta.ChangePercent)), from, to)
480	}
481	
482	func formatPlainCount(value int) string {
483		return strconv.Itoa(value)
484	}
485	
486	func absFloat(value float64) float64 {
487		if value < 0 {
488			return -value
489		}
490		return value
491	}
492

